head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.screenId = "uldmgt50011";
scwin.voidDiv = null;
scwin.delForm = null;

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name init_rowCopy
 * @description dataList 단건 표시 복사 — 진입점에서 1회. 데이터 재적재 시 ev:ondataload 가 다시 부른다.
 * @returns {void}
 * @hidden N
 */
scwin.init_rowCopy = function () {
    const rows = [{ childId: "ipt_keyword", fn: function () { return String((dma_pageContext.get("keyword") ?? "")); } }];
    rows.forEach(function (it) {
        const c = $c.util.getComponent(it.childId);
        if (!c || typeof c.setValue !== "function") { return; }  // as-is 가 서버 렌더로 그리던 반복 행 — 산출에 없는 칸은 건너뛴다
        let v;
        try { v = it.fn(); } catch (e) { $c.exception.handleError(e, { notify: "none", context: "rowCopy:" + it.childId }); return; }
        if (v !== undefined && v !== null && String(v).trim() !== "") { c.setValue(String(v)); }
    });
};

/**
 * @method
 * @name init_pageBody
 * @description 초기화 — page Body
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.init_pageBody = async function () {
    try {
        await scwin.list();

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'uldmgt50011.onpageload' }); }
};

/**
 * @method
 * @name init_loadList
 * @description 초기 목록 조회 — as-is 는 진입 자체가 조회였다
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.init_loadList = async function () {
    // 초기 목록 — as-is 는 진입 자체가 조회였다(근거: self_action). 진입점 합성이 이 단계를 잇는다.
    await scwin.tx_load_list();
};

/**
 * @method
 * @name init_recvParam
 * @description 화면 전환 파라미터 수신 — $c.data.getParameter() 를 dma_pageContext 에 담는다
 * @returns {void}
 * @hidden N
 */
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

scwin.form_listForm = { action: "", method: 'post', target: '' };

/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        scwin.voidDiv = $c.util.getComponent('voidDiv');
        scwin.delForm = delForm;
        scwin.init_rowCopy();
        await scwin.init_loadList();
        await scwin.init_pageBody();
    } catch (e) {
        await $c.exception.handleError(e, { context: 'uldmgt50011.onpageload' });
    }
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name form_1_onsubmit
 * @description form_1 onsubmit 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.form_1_onsubmit = function(e){
    try {
        return false

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'uldmgt50011.form_1_onsubmit' }); }
};

/**
 * @method
 * @name ipt_keyword_onkeyup
 * @description ipt_keyword 키 입력 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.ipt_keyword_onkeyup = async function(e){
    try {
        await scwin.onEnter()

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'uldmgt50011.ipt_keyword_onkeyup' }); }
};

/**
 * @method
 * @name img_81_onclick
 * @description img_81 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.img_81_onclick = async function(e){
    try {
        await scwin.search()

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'uldmgt50011.img_81_onclick' }); }
};

/**
 * @method
 * @name img_99_onclick
 * @description img_99 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.img_99_onclick = async function(e){
    try {
        await scwin.printForm()
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "uldmgt50011.img_99_onclick" });
    }
};

/**
 * @method
 * @name __ev_5_img_99_onclick
 * @description __ev_5_img_99 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.__ev_5_img_99_onclick = async function(e){
    try {
        await scwin.printForm()

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'uldmgt50011.__ev_5_img_99_onclick' }); }
};

/**
 * @method
 * @name img_120_onclick
 * @description img_120 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.img_120_onclick = async function(e){
    try {
        await scwin.execList()

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'uldmgt50011.img_120_onclick' }); }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name tx_printForm
 * @description print Form 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_printForm = async function () {
    const sbmOptions = {
        id: "tx_printForm",
        method: "post",
        action: "/filing/form.do",
        ref: "dma_printFormReq",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

/**
 * @method
 * @name tx_fn_List
 * @description List 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fn_List = async function () {
    const sbmOptions = {
        id: "tx_fn_List",
        method: "post",
        action: "/filing/form.do",
        ref: "dma_ListReq",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

/**
 * @method
 * @name tx_list_xhr
 * @description list xhr 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_list_xhr = async function () {
    // ⛔주소가 없다 — as-is 는 «자기 자신» 에게 제출했는데(`self_submit`) 화면 자신의 액션 URL 을
    //   하나로 못 정했다(후보 0 또는 여럿). 빈 주소로 내보내면 «조용히 엉뚱한 곳» 이다.
    // TODO Stage2: 전환 미완(공급사 드러냄 — 사유 알림 유지) "이 화면의 제출 주소를 아직 정하지 못했습니다(전환 미완) — tx_list_xhr"
    throw { bizMessage: "이 화면의 제출 주소를 아직 정하지 못했습니다(전환 미완) — tx_list_xhr", unresolved: "action:self_submit:tx_list_xhr" };
};

/**
 * @method
 * @name tx_load_list
 * @description load list 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_load_list = async function () {
    const sbmOptions = {
        id: "tx_load_list",
        method: "post",
        action: "/filing/form.do",
        ref: "dma_loadListReq",
        target: "dlt_formAdmInstTpCds=body.content",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name list
 * @description list 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.list = async function () {
    scwin.form_listForm.action = "/filing/form.do";
    $c.util.getComponent('dma_printFormReq').set('method', "findPrintTargetListOnly");
    await scwin.tx_list_xhr();
};

/**
 * @method
 * @name onCompleteResponse
 * @description on Complete Response 처리
 * @param {*} responseText responseText
 * @returns {void}
 * @hidden N
 */
scwin.onCompleteResponse = function (responseText) {
    $c.util.getComponent('formListDiv').innerHTML = responseText;
};

/**
 * @method
 * @name search
 * @description search 처리
 * @param {*} orderBy orderBy
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.search = async function (orderBy) {
    if (orderBy != null) {
        const prevOrderBy = $c.util.getComponent('dma_printFormReq').get('orderBy');
        $c.util.getComponent('dma_printFormReq').set('orderBy', orderBy);
        if (prevOrderBy === orderBy) {
            const ascDiv = $c.util.getComponent('dma_printFormReq').get('ascDiv');
            if (ascDiv === "asc") {
                $c.util.getComponent('dma_printFormReq').set('ascDiv', "desc");
            } else {
                $c.util.getComponent('dma_printFormReq').set('ascDiv', "asc");
            }
        } else {
            $c.util.getComponent('dma_printFormReq').set('ascDiv', "asc");
        }
    } else {
        $c.util.getComponent('dma_printFormReq').set('ascDiv', "asc");
    }
    $c.util.getComponent('dma_printFormReq').set('pageIndex', 1);
    await scwin.list();
};

/**
 * @method
 * @name onEnter
 * @description on Enter 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onEnter = async function () {
    if (event.keyCode === 13) {
        await scwin.search();
    }
};

/**
 * @method
 * @name addForm
 * @description add Form 처리
 * @param {String} formCd formCd
 * @param {*} formVer formVer
 * @param {String} formKorNm formKorNm
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.addForm = async function (formCd, formVer, formKorNm) {
    scwin.voidDiv.setStyle("display", "none");
    if ($c.util.getComponent('targetForm') != null && $c.util.getComponent('targetForm').length != null) {
        if ($c.util.getComponent('targetForm').length >= 20) {
            await $c.win.alert("일괄 인쇄시 20개씩만 선택가능합니다.");
            return;
        }
    }
    if (scwin.existPrintTarget(formCd, formVer)) {
        await $c.win.alert("이미 선택되어 있는 서식입니다.");
        return;
    }
    const ptab = $c.util.getComponent('printTargetList');
    const newTarget = ptab.insertRow();
    const fcd = newTarget.insertCell();
    fcd.id = "targetForm";
    fcd.className = "data_a";
    fcd.innerHTML = formCd + "<input type='hidden' name='printFormCd' value='" + formCd + "' />";
    const fnm = newTarget.insertCell();
    fnm.className = "data_at";
    fnm.innerHTML = formKorNm;
    const fver = newTarget.insertCell();
    fver.className = "data_a";
    fver.innerHTML = formVer + "<input type='hidden' name='printFormVer' value='" + formVer + "' />";
    const del = newTarget.insertCell();
    del.className = "data_a";
    del.innerHTML = "<img src='/img/filing/btn/btn_sub.gif' onclick='delForm(this)' style='cursor:hand' />";
};

/**
 * @method
 * @name existPrintTarget
 * @description exist Print Target 처리
 * @param {String} formCd formCd
 * @param {*} formVer formVer
 * @returns {void}
 * @hidden N
 */
scwin.existPrintTarget = function (formCd, formVer) {
    if (document.listForm.printFormCd == null) {
        return false;
    } else {
        if (document.listForm.printFormCd.length == null || document.listForm.printFormCd.length === 1) {
            if (document.listForm.printFormCd.value === formCd && document.listForm.printFormVer.value === formVer) {
                return true;
            }
        } else {
            for (let i = 0; i < document.listForm.printFormCd.length; i++) {
                if (document.listForm.printFormCd[i].value === formCd && document.listForm.printFormVer[i].value === formVer) {
                    return true;
                }
            }
        }
    }
    return false;
};

function delForm(obj) {
    const trNode = obj.parentNode.parentNode;
    const tbNode = trNode.parentNode;
    tbNode.removeChild(trNode);
    if (document.listForm.printFormCd == null) {
        scwin.voidDiv.setStyle("display", "block");
    }
}

/**
 * @method
 * @name printForm
 * @description print Form 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.printForm = async function () {
    const _url = "/filing/form/ULDMGT50012_i0.jsp";
    const _props = "toolbar=no,menubar=no,scrollbars=yes,status=yes,resizable=yes,width=700,height=700";
    // TODO Stage2: 전환 미완(공급사 드러냄 — 사유 알림 유지) "이 화면의 이동 목적지를 아직 정하지 못했습니다(전환 미완) — "
    await $c.win.openPopup((function (__u) { const __s = String(__u == null ? "" : __u); if (!/\.xml(\?|#|$)/.test(__s)) { throw { bizMessage: "이 화면의 이동 목적지를 아직 정하지 못했습니다(전환 미완) — " + __s, unresolved: "nav:" + __s }; } return __u; })(_url), { id: "printView", popupName: "printView", width: "700", height: "700", resizable: true, scrollbars: true }, {});
    $c.util.getComponent('dma_printFormReq').set('method', "printTargetList");
    scwin.form_listForm.target = "printView";
    scwin.form_listForm.action = "/filing/form.do";
    await scwin.tx_printForm();
};

/**
 * @method
 * @name execList
 * @description exec List 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.execList = async function () {
    scwin.form_listForm.action = "/filing/form.do";
    $c.util.getComponent('dma_printFormReq').set('method', "");
    scwin.form_listForm.target = "";
    await scwin.tx_fn_List();
};
